<script setup lang="ts">import type {Geometry} from '../types/domain';const props=defineProps<{geometry:Geometry;color:string;sx:(v:number)=>number;sy:(v:number)=>number;dashed?:boolean;radius?:number}>();const coords=()=>props.geometry.vertices||props.geometry.corners||[];const points=()=>coords().map(p=>props.sx(p[0])+','+props.sy(p[1])).join(' ');</script><template><polygon v-if="geometry.geometry_type==='polygon'" :points="points()" :fill="dashed?'none':color" :fill-opacity="dashed?0:.08" :stroke="color" stroke-width="2" :stroke-dasharray="dashed?'7 5':undefined"/><polyline v-else-if="geometry.geometry_type==='line'" :points="points()" fill="none" :stroke="color" stroke-width="3" :stroke-dasharray="dashed?'7 5':undefined"/><circle v-else :cx="sx(coords()[0][0])" :cy="sy(coords()[0][1])" :r="radius||8" fill="none" :stroke="color" stroke-width="2"/></template>